response_raw:
// The system shall deploy exactly two AMR robots for material transportation within the factory.
Pr[<=700] ([] N_R == 2)

// Raw materials shall be initially stored in a designated warehouse location.
Pr[<=1] ([] raw_materials[0] == warehouse[0] && raw_materials[1] == warehouse[1])

// Robot1 shall be able to pick up raw materials from the warehouse.
Pr[<=700] (<> robot_inventory[0][0] == 1)

// Robot2 shall be able to pick up raw materials from the warehouse.
Pr[<=700] (<> robot_inventory[1][0] == 1)

// Upon receiving a transport order, Robot1 shall transition from 'Idle' to 'Active' mode.
Pr[<=1] ([] Factory_Pipeline_robot1_def.init_robot1)

// Upon receiving a transport order, Robot2 shall transition from 'Idle' to 'Active' mode.
Pr[<=1] ([] Factory_Pipeline_robot2_def.init_robot2)

// Robot1 shall avoid collisions with ARM2.
Pr[<=7000] (<> robPositionX[0] == robPositionX[1] && robPositionY[0] == robPositionY[1])

// Robot2 shall avoid collisions with Robot1.
Pr[<=7000] (<> robPositionX[1] == robPositionX[0] && robPositionY[1] == robPositionY[0])

// Robot1 shall not enter forbidden zones during navigation.
Pr[<=700] (<> !isValidPosition(robPositionX[0], robPositionY[0]))

// Robot2 shall not enter forbidden zones during navigation.
Pr[<=700] (<> !isValidPosition(robPositionX[1], robPositionY[1]))

// Robot1 shall ensure that its battery level does not reach zero during execution of the transportation workflow.
Pr[<=700] (<> batteryCharge[0] <= 0)

// Robot2 shall ensure that its battery level does not reach zero during execution of the transportation workflow.
Pr[<=700] (<> batteryCharge[1] <= 0)

// The robots shall transport raw materials from the warehouse to the loading location of the surface texturization station.
Pr[<=700] (<> pow(robPositionX[0] - surface_texturization_start[0], 2) + pow(robPositionY[0] - surface_texturization_start[1], 2) <= 900 && robot_inventory[0][0] == 1)

// The robots shall transport raw materials from the warehouse to the loading location of the surface texturization station.
Pr[<=700] (<> pow(robPositionX[1] - surface_texturization_start[0], 2) + pow(robPositionY[1] - surface_texturization_start[1], 2) <= 900 && robot_inventory[1][0] == 1)

// The robots shall collect processed materials from the unloading location of the surface texturization station and deliver them to the loading location of the laser station.
Pr[<=700] (<> pow(robPositionX[0] - laser_start[0], 2) + pow(robPositionY[0] - laser_start[1], 2) <= 900 && robot_inventory[0][0] == 1)

// The robots shall collect processed materials from the unloading location of the surface texturization station and deliver them to the loading location of the laser station.
Pr[<=700] (<> pow(robPositionX[1] - laser_start[0], 2) + pow(robPositionY[1] - laser_start[1], 2) <= 900 && robot_inventory[1][0] == 1)

// The robots shall collect processed materials from the unloading location of the laser station and deposit them in the loading area.
Pr[<=700] (<> pow(robPositionX[0] - loading_area[0], 2) + pow(robPositionY[0] - loading_area[1], 2) <= 900 && robot_inventory[0][0] == 1)

// The robots shall collect processed materials from the unloading location of the laser station and deposit them in the loading area.
Pr[<=700] (<> pow(robPositionX[1] - loading_area[0], 2) + pow(robPositionY[1] - loading_area[1], 2) <= 900 && robot_inventory[1][0] == 1)

// Each robot shall be able to carry exactly one piece of raw or processed material at a time.
Pr[<=700] (<> robot_inventory[0][0] > 1)

// The robots shall maintain a safe operating speed to prevent damage to materials, equipment, or infrastructure.
Pr[<=700] (<> rm_1.V > rm_1._v_max)

// The robots shall maintain a safe operating speed to prevent damage to materials, equipment, or infrastructure.
Pr[<=700] (<> rm_2.V > rm_2._v_max)
